// src/services/configService.js
import { showGlobalNotification } from '@/utils/notificationHandler.js';

// 默认配置
const DEFAULT_CONFIG = {
    backendIp: 'localhost',
    backendPort: 5002
};

class ConfigService {
    constructor() {
        this.config = this.loadConfig();
    }

    // 加载配置
    loadConfig() {
        try {
            const savedConfig = localStorage.getItem('backendConfig');
            if (savedConfig) {
                return JSON.parse(savedConfig);
            }
        } catch (error) {
            showGlobalNotification('加载配置失败', 'error');
        }
        return DEFAULT_CONFIG;
    }

    // 保存配置
    saveConfig(config) {
        try {
            localStorage.setItem('backendConfig', JSON.stringify(config));
            this.config = config;
        } catch (error) {
            showGlobalNotification('保存配置失败', 'error');
        }
    }

    // 获取配置
    getConfig() {
        return this.config;
    }

    // 获取后端基础URL
    getBackendBaseUrl() {
        return `http://${this.config.backendIp}:${this.config.backendPort}`;
    }

    // 获取WebSocket URL
    getWebSocketUrl(path) {
        return `ws://${this.config.backendIp}:${this.config.backendPort}${path}`;
    }

    // 重置为默认配置
    resetToDefault() {
        this.saveConfig(DEFAULT_CONFIG);
        return DEFAULT_CONFIG;
    }
}

// 导出单例
export const configService = new ConfigService();
export default configService;
