<!--/views/Control.vue-->
<template>
    <div class="control-container">
        <div class="header">
            <h1><i class="fas fa-project-diagram"></i> 智能监控系统</h1>
            <nav class="main-nav">
                <ul>
                    <li>
                        <router-link to="/control" class="nav-link" active-class="active">
                            <i class="fas fa-desktop"></i> 设备控制
                        </router-link>
                    </li>
                    <li>
                        <router-link to="/monitor" class="nav-link" active-class="active">
                            <i class="fas fa-video"></i> 监控中心
                        </router-link>
                    </li>
                </ul>
            </nav>
        </div>

        <div class="content">
            <!-- ========================= 左侧面板 ========================= -->
            <div class="left-panel">
                <!-- 设备列表 -->
                <div class="device-panel">
                    <div class="panel-header">
                        <h2><i class="fas fa-desktop"></i> 发现的设备 ({{ allDevices.length }})</h2>
                        <div class="header-buttons">
                            <Tooltip content="重新扫描设备">
                                <button class="btn-refresh-small" @click="sendDiscoveryMessage" :disabled="isDiscoveryWaiting">
                                    <i class="fas fa-sync-alt" :class="{ 'fa-spin': isDiscoveryWaiting }"></i>
                                </button>
                            </Tooltip>
                            <Tooltip content="设置拓扑包中转">
                                <button class="btn-settings-small" @click="openTopologySettings">
                                    <i class="fas fa-cog"></i>
                                </button>
                            </Tooltip>
                        </div>
                    </div>

                    <div v-if="allDevices.length === 0" class="empty-state">
                        <i class="fas fa-search"></i>
                        <p v-if="isDiscoveryWaiting">扫描中，请等待约10秒...</p>
                        <div v-else>
                            <p>无设备</p>
                            <small>点击右上角搜索设备</small>
                        </div>
                    </div>

                    <!-- 设备列表模板部分 -->
                    <div v-else class="device-list">
                        <!-- 云设备 -->
                        <div v-if="cloudDevices.length > 0" class="device-category">
                            <div class="category-header" @click="toggleDeviceCategory('cloud')">
                                <h4>
                                    <i class="fas fa-cloud"></i>
                                    云计算端 ({{ cloudDevices.length }})
                                    <i class="category-arrow fas"
                                       :class="deviceCategoryCollapsed.cloud ? 'fa-chevron-down' : 'fa-chevron-up'"></i>
                                </h4>
                            </div>
                            <transition name="slide-down">
                                <div v-show="!deviceCategoryCollapsed.cloud" class="category-content">
                                    <div v-for="device in cloudDevices" :key="device.mac" class="device-item" @click="selectDeviceFromList(device)">
                                        <div class="device-icon" :style="{ background: getAvatarColor(device.mac) }">
                                            <i class="fas fa-cloud"></i>
                                        </div>
                                        <div class="device-info">
                                            <div class="device-name">{{ getDeviceShowName(device.mac) }}</div>
                                            <div class="device-time">最后活跃: {{ formatDeviceTime(device.lastSeen) }}</div>
                                        </div>
                                        <Tooltip :content="getStatusTooltip(device.status)">
                                            <div class="device-status" :class="device.status">
                                                <i class="fas fa-circle"></i>
                                                <span class="status-text">
                                                    {{ device.status === 'online' ? '在线' : 
                                                       device.status === 'offline' ? '离线' : 
                                                       device.status === 'suspect_offline' ? '等待' : 
                                                       device.status === 'communicable' ? '连接' : 
                                                       device.status === 'communication_failure' ? '故障' : '未知' }}
                                                </span>
                                            </div>
                                        </Tooltip>
                                    </div>
                                </div>
                            </transition>
                        </div>

                        <!-- 监控设备 -->
                        <div v-if="monitorDevices.length > 0" class="device-category">
                            <div class="category-header" @click="toggleDeviceCategory('monitor')">
                                <h4>
                                    <i class="fas fa-desktop"></i>
                                    监控端 ({{ monitorDevices.length }})
                                    <i class="category-arrow fas"
                                       :class="deviceCategoryCollapsed.monitor ? 'fa-chevron-down' : 'fa-chevron-up'"></i>
                                </h4>
                            </div>
                            <transition name="slide-down">
                                <div v-show="!deviceCategoryCollapsed.monitor" class="category-content">
                                    <div v-for="device in monitorDevices" :key="device.mac" class="device-item" @click="selectDeviceFromList(device)">
                                        <div class="device-icon" :style="{ background: getAvatarColor(device.mac) }">
                                            <i class="fas fa-desktop"></i>
                                        </div>
                                        <div class="device-info">
                                            <div class="device-name">{{ getDeviceShowName(device.mac) }}</div>
                                            <div class="device-time">最后活跃: {{ formatDeviceTime(device.lastSeen) }}</div>
                                        </div>
                                        <Tooltip :content="getStatusTooltip(device.status)">
                                            <div class="device-status" :class="device.status">
                                                <i class="fas fa-circle"></i>
                                                <span class="status-text">
                                                    {{ device.status === 'online' ? '在线' : 
                                                       device.status === 'offline' ? '离线' : 
                                                       device.status === 'suspect_offline' ? '等待' : 
                                                       device.status === 'communicable' ? '连接' : 
                                                       device.status === 'communication_failure' ? '故障' : '未知' }}
                                                </span>
                                            </div>
                                        </Tooltip>
                                    </div>
                                </div>
                            </transition>
                        </div>

                        <!-- 其他设备 -->
                        <div v-if="otherDevices.length > 0" class="device-category">
                            <div class="category-header" @click="toggleDeviceCategory('other')">
                                <h4>
                                    <i class="fas fa-question-circle"></i>
                                    其他设备 ({{ otherDevices.length }})
                                    <i class="category-arrow fas"
                                       :class="deviceCategoryCollapsed.other ? 'fa-chevron-down' : 'fa-chevron-up'"></i>
                                </h4>
                            </div>
                            <transition name="slide-down">
                                <div v-show="!deviceCategoryCollapsed.other" class="category-content">
                                    <div v-for="device in otherDevices" :key="device.mac" class="device-item" @click="selectDeviceFromList(device)">
                                        <div class="device-icon" :style="{ background: getAvatarColor(device.mac) }">
                                            <i class="fas fa-question-circle"></i>
                                        </div>
                                        <div class="device-info">
                                            <div class="device-name">{{ getDeviceShowName(device.mac) }}</div>
                                            <div class="device-time">最后活跃: {{ formatDeviceTime(device.lastSeen) }}</div>
                                        </div>
                                        <Tooltip :content="getStatusTooltip(device.status)">
                                            <div class="device-status" :class="device.status">
                                                <i class="fas fa-circle"></i>
                                                <span class="status-text">
                                                    {{ device.status === 'online' ? '在线' : 
                                                       device.status === 'offline' ? '离线' : 
                                                       device.status === 'suspect_offline' ? '等待' : 
                                                       device.status === 'communicable' ? '连接' : 
                                                       device.status === 'communication_failure' ? '故障' : '未知' }}
                                                </span>
                                            </div>
                                        </Tooltip>
                                    </div>
                                </div>
                            </transition>
                        </div>
                    </div>
                </div>

                <!-- 消息列表（按设备分类） -->
                <div class="topic-panel">
                    <div class="panel-header">
                        <h2><i class="fas fa-list"></i> 消息列表</h2>
                        <Tooltip content="刷新拓扑">
                            <button class="btn-refresh-small" @click="refreshTopology" :disabled="topologyLoading">
                                <i class="fas fa-sync-alt" :class="{ 'fa-spin': topologyLoading }"></i>
                            </button>
                        </Tooltip>
                    </div>

                    <div v-if="groupedMessages.length === 0" class="empty-state">
                        <i class="fas fa-comment-slash"></i>
                        <p>暂无消息</p>
                        <small>等待设备消息或点击刷新拓扑</small>
                    </div>

                    <div v-else class="message-list">
                        <!-- 设备消息列表 -->
                        <div v-for="(deviceMsg, index) in groupedMessages" 
                             :key="deviceMsg.mac"
                             class="device-message-item"
                             :class="{ 'selected': selectedDeviceMac === deviceMsg.mac }"
                             @click="selectDeviceMac(deviceMsg.mac)"
                        >
                            <div class="device-avatar" :style="{ background: getAvatarColor(deviceMsg.mac || 'unknown') }">
                                <i class="fas fa-device"></i>
                            </div>
                            <div class="device-message-content">
                                <div class="device-header">
                                    <div class="device-name">{{ deviceMsg.deviceName }}</div>
                                    <div class="message-time">
                                        {{ formatMessageTime(deviceMsg.latestMessage.receivedAt || Date.now()) }}
                                    </div>
                                </div>
                                <div class="latest-message">
                                    <pre>{{ deviceMsg.latestMessage.msg }}</pre>
                                </div>
                                <div v-if="deviceMsg.messageCount > 1" class="message-count">
                                    {{ deviceMsg.messageCount }}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- 拓扑信息 -->
                <div class="topic-panel">
                    <h2><i class="fas fa-network-wired"></i> 网络拓扑</h2>

                    <div v-if="topologyLoading" class="loading">
                        <div class="spinner"></div>
                        <p>加载拓扑中...</p>
                    </div>

                    <div v-else-if="!latestTopologyId" class="empty-state">
                        <i class="fas fa-network-wired"></i>
                        <p>暂无拓扑信息</p>
                        <button class="btn-small btn-primary" @click="refreshTopology">
                            刷新拓扑
                        </button>
                    </div>

                    <div v-else class="topology-info">
                        <div class="topology-header">
                            <span>拓扑ID: {{ latestTopologyId }}</span>
                            <span>设备数量: {{ Object.keys(topology).length }}</span>
                        </div>
                        <div class="device-nodes">
                            <div v-for="(node, mac) in topology" 
                                 :key="mac"
                                 class="device-node"
                            >
                                <div class="node-header">
                                    <span>{{ getDeviceShowName(mac) }}</span>
                                    <button class="btn-small" @click="showNicknameDialog(mac)">
                                        <i class="fas fa-edit"></i>
                                    </button>
                                </div>
                                <div class="node-connections">
                                    <span v-for="(role, neighborMac) in node" 
                                          :key="neighborMac"
                                          class="connection"
                                    >
                                        {{ getDeviceShowName(neighborMac) }}
                                    </span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <!-- ========================= 右侧消息面板 ========================= -->
            <div class="right-panel">
                <div v-if="!selectedDeviceMac" class="empty-state">
                    <i class="fas fa-mouse-pointer"></i>
                    <p>请从左侧选择一个设备</p>
                </div>

                <div v-else>
                    <!-- 消息面板 -->
                    <div class="message-panel">
                        <div class="topic-header">
                            <div class="device-info">
                                <i class="fas fa-server"></i>
                                <div>
                                    <h2>{{ selectedDeviceMac === 'all' ? '全部消息' : getDeviceShowName(selectedDeviceMac) }}</h2>
                                    <div class="topic-status online">
                                        在线
                                    </div>
                                </div>
                            </div>

                            <div class="stats">
                                <div class="stat-card">
                                    <div class="stat-label">消息数量</div>
                                    <div class="stat-value">{{ currentDeviceMessages.length }}</div>
                                </div>
                                <div class="stat-card">
                                    <div class="stat-label">设备状态</div>
                                    <div class="stat-value online">在线</div>
                                </div>
                                <div class="stat-card">
                                    <div class="stat-label">最后活动</div>
                                    <div class="stat-value">{{ lastUpdateTime }}</div>
                                </div>
                            </div>
                        </div>

                        <div class="message-section">
                            <div class="message-header">
                                <h3><i class="fas fa-history"></i> 消息记录 ({{ currentDeviceMessages.length }}条)</h3>
                                <div class="last-update">
                                    <small>最后更新: {{ lastUpdateTime }}</small>
                                </div>
                            </div>

                            <!-- 消息选项卡 -->
                            <div class="message-tabs">
                                <button class="tab-button"
                                        :class="{ active: activeMessageTab === 'formatted' }"
                                        @click="activeMessageTab = 'formatted'">
                                    <i class="fas fa-comments"></i> 格式化消息
                                </button>
                                <button class="tab-button"
                                        :class="{ active: activeMessageTab === 'raw' }"
                                        @click="activeMessageTab = 'raw'">
                                    <i class="fas fa-code"></i> 原始消息
                                </button>
                            </div>

                            <div v-if="loadingMessages" class="loading">
                                <div class="spinner"></div>
                                <p>加载消息中...</p>
                            </div>

                            <div v-else-if="currentDeviceMessages.length === 0" class="empty-state">
                                <i class="fas fa-comment-slash"></i>
                                <p>暂无消息记录</p>
                            </div>

                            <div v-else class="message-content">
                                <!-- 格式化消息视图 -->
                                <div v-show="activeMessageTab === 'formatted'" class="formatted-messages">
                                    <div v-for="(msg, index) in currentDeviceMessages"
                                         :key="index"
                                         class="chat-message">
                                        <div class="message-avatar" :style="{ background: getAvatarColor(msg.source_mac || 'unknown') }" @contextmenu.prevent="onAvatarRightClick($event, msg)">
                                            <i class="fas fa-device"></i>
                                        </div>
                                        <div class="message-body">
                                            <div class="message-header">
                                                <span class="message-user">{{ getMessageSender(msg) }}</span>
                                                <span class="message-time">{{ formatMessageTime(msg.receivedAt || Date.now()) }}</span>
                                            </div>
                                            <div class="message-text">
                                                <template v-if="msg.msg">
                                                    <span v-if="msg.target && msg.target !== 'p2p'" class="mention-tag">@{{ getTargetShowName(msg.target) }}</span>
                                                    {{ msg.msg }}
                                                </template>
                                                <template v-else>
                                                    <span class="unsupported-message">不支持的消息，请查看原始消息</span>
                                                </template>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <!-- 原始消息视图 -->
                                <div v-show="activeMessageTab === 'raw'" class="raw-messages">
                                    <div v-for="(msg, index) in currentDeviceMessages"
                                         :key="index"
                                         class="message-item">
                                        <div class="message-content">
                                            {{ JSON.stringify(msg, null, 2) }}
                                        </div>
                                        <div class="message-time">{{ formatMessageTime(msg.receivedAt || Date.now()) }}</div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <!-- 消息发送区域 -->
                        <div class="message-sender">
                            <div class="sender-container">
                                <!-- 输入区域 -->
                                <div class="input-container">
                                    <div class="message-input-wrapper">
                                        <!-- 设备选择列表 -->
                                        <div v-if="showDeviceList" class="device-list-dropdown">
                                            <div v-for="(device, index) in filteredDevices" 
                                                 :key="device.user || device.mac"
                                                 :class="['device-option', { 'selected': index === selectedDeviceIndex }]"
                                                 @click="selectDevice(device)">
                                                <i class="fas fa-user"></i>
                                                <span>{{ device.mac ? getDeviceShowName(device.mac) : (device.user || '未知设备') }}</span>
                                            </div>
                                            <div v-if="filteredDevices.length === 0" class="empty-device-list">
                                                无匹配设备
                                            </div>
                                        </div>
                                        
                                        <!-- 目标设备标签 -->
                                        <div v-if="selectedTargetDevice" class="target-tag" @click="clearTargetDevice">
                                            @{{ selectedTargetDevice.mac ? getDeviceShowName(selectedTargetDevice.mac) : (selectedTargetDevice.user || selectedTargetDevice.mac) }}
                                            <button class="remove-tag">
                                                <i class="fas fa-times"></i>
                                            </button>
                                        </div>
                                        
                                        <!-- exec命令提示条 -->
                                        <div v-if="isExecCommand && (historyIndex === -1)" class="exec-command-tip">
                                            <i class="fas fa-info-circle"></i>
                                            <span>提示：在exec命令中，使用 Ctrl+↑↓ 导航历史命令</span>
                                        </div>
                                        
                                        <!-- 功能菜单模式 -->
                                        <div v-if="showFunctionMenu" class="function-menu-container">
                                            <div class="function-menu-items">
                                                <div
                                                    v-for="(item, index) in functionMenuItems"
                                                    :key="index"
                                                    class="function-menu-item"
                                                    @click="handleMenuItemClick(item, $event)"
                                                >
                                                    <span>{{ item.name || 'Unnamed' }}</span>
                                                    <span v-if="item.submenu" class="menu-icon">
                                                        <i class="fas fa-bars"></i>
                                                    </span>
                                                    <span v-else-if="item.input" class="menu-icon">
                                                        <i class="fas fa-edit"></i>
                                                    </span>
                                                </div>
                                            </div>
                                            <button @click="toggleFunctionMenu" class="keyboard-button">
                                                <i class="fas fa-keyboard"></i>
                                            </button>
                                        </div>
                                        
                                        <!-- 输入框模式 -->
                                        <div v-else class="input-mode-container">
                                            <!-- 输入框容器，用于定位索引提示 -->
                                            <div class="input-with-index">
                                                <textarea ref="messageInput"
                                                          v-model="messageText"
                                                          placeholder="输入消息... (Shift+Enter换行，↑↓键导航历史消息)"
                                                          :class="['message-input', { 'exec-command': isExecCommand }]"
                                                          rows="1"
                                                          @keydown="handleKeydown"
                                                          @input="handleInput"
                                                          @focus="onInputFocus"
                                                          @blur="onInputBlur"></textarea>
                                                <!-- 历史消息索引提示 -->
                                                <div v-if="historyIndex >= 0" class="history-index">
                                                    [{{ historyIndex }}/{{ Math.max(0, messageHistory[selectedDeviceMac]?.length - 1 || 0) }}]
                                                </div>
                                            </div>
                                            <button @click="toggleFunctionMenu" class="menu-button">
                                                <i class="fas fa-bars"></i>
                                            </button>
                                        </div>
                                        
                                        <!-- 弹出菜单 -->
                                        <PopupMenu
                                            v-model:visible="showMenuPopup"
                                            :items="activeMenuItem?.submenu || []"
                                            :trigger-element="menuTriggerElement"
                                            :position="'top'"
                                            @item-click="handleMenuPopupItemClick"
                                        />
                                    </div>

                                    <button @click="sendMessage"
                                            :disabled="!messageText.trim() || sendingMessage"
                                            class="send-button">
                                        <i class="fas fa-paper-plane" :class="{ 'fa-spin': sendingMessage }"></i>
                                        {{ sendingMessage ? '发送中...' : '发送' }}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <div v-if="showContextMenu"
         class="context-menu"
         :style="{ left: contextMenuX + 'px', top: contextMenuY + 'px' }">
        <div class="context-menu-item" @click="mentionUser">
            <i class="fas fa-at"></i> 提及
        </div>
        <div class="context-menu-item" @click="sendHeartbeat">
            <i class="fas fa-heartbeat"></i> 心跳
        </div>
        <div class="context-menu-item" @click="testItem1">
            <i class="fas fa-vial"></i> 测试项1
        </div>
        <div class="context-menu-item" @click="testItem2">
            <i class="fas fa-vial"></i> 测试项2
        </div>
    </div>

    <!-- 备注设置对话框 -->
    <transition name="dialog">
        <div v-if="nicknameDialogVisible" class="dialog-overlay" @click="closeNicknameDialog">
            <div class="dialog" @click.stop>
                <h3>设置设备备注</h3>
                <div class="form-group">
                    <label>设备MAC</label>
                    <input type="text" v-model="currentDeviceMac" disabled>
                </div>
                <div class="form-group">
                    <label>备注</label>
                    <input type="text" v-model="currentDeviceNickname" placeholder="请输入设备备注">
                </div>
                <div class="dialog-actions">
                    <button class="btn-secondary" @click="closeNicknameDialog">
                        取消
                    </button>
                    <button class="btn-primary" @click="saveDeviceNickname">
                        保存
                    </button>
                </div>
            </div>
        </div>
    </transition>

    <!-- 拓扑包中转设置对话框 -->
    <transition name="dialog">
        <div v-if="topologySettingsVisible" class="dialog-overlay" @click="closeTopologySettings">
            <div class="dialog" @click.stop>
                <h3>设置拓扑包中转</h3>
                <div class="form-group">
                    <label>转发地址 (forward_addr)</label>
                    <input type="text" v-model="topologySettings.forward_addr" placeholder="例如: 192.168.1.100:5000">
                </div>
                <div class="form-group">
                    <label>转发MAC (forward_mac)</label>
                    <input type="text" v-model="topologySettings.forward_mac" placeholder="例如: aa:bb:cc:dd:ee:ff">
                </div>
                <div class="dialog-actions">
                    <button class="btn-secondary" @click="closeTopologySettings">
                        取消
                    </button>
                    <button class="btn-primary" @click="saveTopologySettings">
                        保存
                    </button>
                </div>
            </div>
        </div>
    </transition>
</template>

<script setup>
    // ========================= 导入部分 =========================
    import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue';
import PopupMenu from '../components/PopupMenu.vue';
import { useRouter } from 'vue-router';
import { useAuth } from '@/composables/useAuth';
import { useDeviceControl } from '@/composables/useDeviceControl';
import { stpApi } from '@/services/stpApi';
import { showGlobalNotification } from '@/utils/notificationHandler.js';
import Tooltip from '@/components/Tooltip.vue';

    // ========================= 变量声明 =========================
    const router = useRouter();
    const { userInitial, logout, getUserId } = useAuth();
    const {
        topics,
        loadingTopics,
        selectedTopic,
        messages,
        loadingMessages,
        topicInfo,
        allDevices,
        cloudDevices,
        monitorDevices,
        otherDevices,
        deviceTypeMap,
        deviceIconMap,
        fetchTopics,
        selectTopic,
        formatTime,
        sendDiscoveryMessage,
        startDeviceDiscovery,
        stopDeviceDiscovery,
        isDiscoveryWaiting,
        publishMessage,
        // 新添加的状态和方法
        topology,
        latestTopologyId,
        topologyLoading,
        messageDictionary,
        selectedDeviceMac,
        groupedMessages,
        currentDeviceMessages,
        refreshTopology,
        setDeviceNickname,
        getDeviceNickname,
        getDeviceShowName,
        selectDeviceMac,
        initWebSockets
    } = useDeviceControl();

    // 昵称设置对话框
    const nicknameDialogVisible = ref(false);
    const currentDeviceMac = ref('');
    const currentDeviceNickname = ref('');

    // 拓扑包中转设置对话框
    const topologySettingsVisible = ref(false);
    const topologySettings = ref({
        forward_addr: '',
        forward_mac: ''
    });

    // 显示昵称设置对话框
    const showNicknameDialog = (mac) => {
        currentDeviceMac.value = mac;
        currentDeviceNickname.value = getDeviceNickname(mac);
        nicknameDialogVisible.value = true;
    };

    // 保存设备昵称
    const saveDeviceNickname = () => {
        if (currentDeviceMac.value && currentDeviceNickname.value) {
            setDeviceNickname(currentDeviceMac.value, currentDeviceNickname.value);
