            let parsedMsg = { ...msg };

            if (typeof msg.msg === 'string') {
                try {
                    const normalizedMsg = msg.msg.replace(/'/g, '"');
                    const jsonMatch = normalizedMsg.match(/\{.*\}/);
                    if (jsonMatch) {
                        const jsonData = JSON.parse(jsonMatch[0]);
                        parsedMsg = {
                            ...parsedMsg,
                            ...jsonData,
                            originalMsg: msg.msg
                        };
                    }
                } catch (e) {
                    showGlobalNotification('消息解析失败，使用原始格式', 'warning');
                    parsedMsg.originalMsg = msg.msg;
                }
            }

            return {
                user: parsedMsg.user || '未知用户',
                type: parsedMsg.type || 'unknown',
                time: parsedMsg.time || Math.floor(Date.now() / 1000),
                msg: parsedMsg.msg || parsedMsg.originalMsg || '',
                target: parsedMsg.target || 'all',
