    // 消息发送相关方法
    const handleInput = () => {
        const text = messageText.value;

        // 检测是否为exec命令
        isExecCommand.value = text.trim().startsWith('exec ');

        // 如果正在导航历史命令，且用户修改了输入内容，退出导航模式
        if (historyIndex.value >= 0) {
            // 替换tempMessage为当前输入内容
            tempMessage.value = text;
            // 复位历史索引，退出导航模式
            historyIndex.value = -1;
        }

        // 只在广播消息中启用@提及功能
        if (selectedDeviceMac.value === 'broadcast' && text.startsWith('@') && !selectedTargetDevice.value) {
            const query = text.slice(1).trim();
            filterDevices(query);
            showDeviceList.value = true;
        } else if (!text.startsWith('@')) {
            showDeviceList.value = false;
        }
    };

    const filterDevices = (query) => {
        if (!query) {
            filteredDevices.value = availableDevices.value;
        } else {
            filteredDevices.value = availableDevices.value.filter(device => {
                // 如果设备有MAC地址，使用显示名称来过滤
                if (device.mac) {
                    const showName = getDeviceShowName(device.mac);
                    return showName.toLowerCase().includes(query.toLowerCase());
                }
                // 否则使用user字段来过滤
                return device.user.toLowerCase().includes(query.toLowerCase());
            });
        }
        selectedDeviceIndex.value = -1;
    };

    const handleKeydown = (event) => {
        if (event.key === 'Escape' && showDeviceList.value) {
            closeDeviceList();
            event.preventDefault();
            return;
        }

        const isEnterKey = event.key === 'Enter' || event.keyCode === 13;
        if (isEnterKey) {
            if (!event.shiftKey) {
                event.preventDefault();
                if (showDeviceList.value && selectedDeviceIndex.value >= 0) {
                    selectDevice(filteredDevices.value[selectedDeviceIndex.value]);
                } else if (!showDeviceList.value) {
                    sendMessage();
                }
            }
        }

        if (showDeviceList.value) {
            if (event.key === 'ArrowDown') {
                selectedDeviceIndex.value = Math.min(
                    selectedDeviceIndex.value + 1,
                    filteredDevices.value.length - 1
                );
                event.preventDefault();
                scrollToSelectedDevice();
            } else if (event.key === 'ArrowUp') {
                selectedDeviceIndex.value = Math.max(selectedDeviceIndex.value - 1, -1);
                event.preventDefault();
                scrollToSelectedDevice();
            } else if (event.key === 'Tab' && selectedDeviceIndex.value >= 0) {
                selectDevice(filteredDevices.value[selectedDeviceIndex.value]);
                event.preventDefault();
            }
        } else {
            // 处理历史消息导航
            if (event.key === 'ArrowUp') {
                if (historyIndex.value >= 0) {
                    // 已经开始导航历史命令，继续导航
                    event.preventDefault();
                    if (selectedDeviceMac.value) {
                        // 确保当前会话的历史消息列表存在
                        if (!messageHistory.value[selectedDeviceMac.value]) {
                            messageHistory.value[selectedDeviceMac.value] = [];
                        }
                        
                        const history = messageHistory.value[selectedDeviceMac.value];
                        
                        // 增加索引，但不超过历史消息列表长度-1
                        if (historyIndex.value < history.length - 1) {
                            historyIndex.value++;
                            messageText.value = history[historyIndex.value];
                            // 检查当前历史消息是否以exec开头，更新exec命令状态
                            isExecCommand.value = history[historyIndex.value].trim().startsWith('exec ');
                        } else {
                            // 索引到达最大值，提示没有更早的命令了
                            showGlobalNotification('没有更早的命令了', 'info');
                        }
                    }
                } else if (!isExecCommand.value && messageText.value.trim() === '') {
                    // 不在输入exec命令，且输入框为空，开始导航历史命令
                    event.preventDefault();
                    if (selectedDeviceMac.value) {
                        // 确保当前会话的历史消息列表存在
                        if (!messageHistory.value[selectedDeviceMac.value]) {
                            messageHistory.value[selectedDeviceMac.value] = [];
                        }
                        
                        const history = messageHistory.value[selectedDeviceMac.value];
                        
                        // 保存当前输入（空）
                        tempMessage.value = messageText.value;
                        
                        // 如果有历史消息，开始导航
                        if (history.length > 0) {
                            historyIndex.value = 0;
                            messageText.value = history[historyIndex.value];
                            // 检查当前历史消息是否以exec开头，更新exec命令状态
                            isExecCommand.value = history[historyIndex.value].trim().startsWith('exec ');
                        } else {
                            // 没有历史命令，提示用户
                            showGlobalNotification('您还未输入过历史命令', 'info');
                        }
                    }
                }
                // 否则，让上键保持默认行为（定位光标）
            } else if (event.key === 'ArrowDown') {
                if (historyIndex.value >= 0) {
                    // 已经开始导航历史命令，继续导航
                    event.preventDefault();
                    if (selectedDeviceMac.value) {
                        // 确保当前会话的历史消息列表存在
                        if (!messageHistory.value[selectedDeviceMac.value]) {
                            messageHistory.value[selectedDeviceMac.value] = [];
                        }
                        
                        // 减少索引
                        if (historyIndex.value > 0) {
                            historyIndex.value--;
                            messageText.value = messageHistory.value[selectedDeviceMac.value][historyIndex.value];
                            // 检查当前历史消息是否以exec开头，更新exec命令状态
                            isExecCommand.value = messageHistory.value[selectedDeviceMac.value][historyIndex.value].trim().startsWith('exec ');
                        } else if (historyIndex.value === 0) {
                            // 回到初始状态，恢复临时存储的内容
                            historyIndex.value = -1;
                            messageText.value = tempMessage.value;
                            // 重置exec命令状态
                            isExecCommand.value = tempMessage.value.trim().startsWith('exec ');
                        }
                    }
                } else if (!isExecCommand.value) {
                    // 索引已经是-1，提示已经是最新命令
                    event.preventDefault();
                    showGlobalNotification('已经是最新命令', 'info');
                }
            }
            
            // 处理exec命令中的Ctrl+方向键导航历史命令
            // 只在正在输入的exec命令中生效（historyIndex === -1），不在历史导航中的exec命令中生效
            if (isExecCommand.value && event.ctrlKey && historyIndex.value === -1) {
                if (event.key === 'ArrowUp') {
                    event.preventDefault();
                    if (selectedDeviceMac.value) {
                        // 确保当前会话的历史消息列表存在
