                const selectedOption = dropdown?.querySelectorAll('.device-option')[selectedDeviceIndex.value];
                if (selectedOption && dropdown) {
                    // 计算选中项的位置
                    const optionTop = selectedOption.offsetTop;
                    const optionHeight = selectedOption.offsetHeight;
                    const dropdownTop = dropdown.scrollTop;
                    const dropdownHeight = dropdown.clientHeight;
                    
                    // 检查是否需要滚动
                    if (optionTop < dropdownTop) {
                        // 选中项在可视区域上方
                        dropdown.scrollTop = optionTop;
                    } else if (optionTop + optionHeight > dropdownTop + dropdownHeight) {
                        // 选中项在可视区域下方
                        dropdown.scrollTop = optionTop + optionHeight - dropdownHeight;
                    }
                }
            });
        }
    };
    
    // 功能菜单相关方法
    const toggleFunctionMenu = () => {
        showFunctionMenu.value = !showFunctionMenu.value;
        // 关闭所有菜单
        showMenuPopup.value = false;
    };
    
    const handleMenuItemClick = (item, event) => {
        if (item.submenu) {
            // 展开子菜单
            showMenuPopup.value = true;
            activeMenuItem.value = item;
            // 获取触发元素
            menuTriggerElement.value = event.currentTarget;
        } else if (item.input) {
            // 跳转到输入框并填充内容
            showFunctionMenu.value = false;
            messageText.value = item.input;
        } else if (item.message) {
            // 设置消息内容并发送
            messageText.value = item.message;
            sendMessage();
        }
    };
    
    const handleMenuPopupItemClick = (item) => {
        if (item.input) {
            // 跳转到输入框并填充内容
            showFunctionMenu.value = false;
            messageText.value = item.input;
        } else if (item.message) {
            // 设置消息内容并发送
            messageText.value = item.message;
            sendMessage();
        }
        showMenuPopup.value = false;
    };

    const selectDevice = (device) => {
        selectedTargetDevice.value = device;
        messageText.value = '';
        showDeviceList.value = false;

        // 添加滚动和聚焦
        nextTick(() => {
            scrollToMessageSender();
            if (messageInput.value) {
                messageInput.value.focus();
            }
        });
    };

    const clearTargetDevice = () => {
        selectedTargetDevice.value = null;
        messageText.value = '';

        // 聚焦到输入框
        if (messageInput.value) {
