        selectedDeviceIndex.value = -1;
    };

    const onInputBlur = () => {
        setTimeout(() => {
            showDeviceList.value = false;
        }, 200);
    };

    const onInputFocus = () => {
        if (messageText.value.startsWith('@') && !selectedTargetDevice.value) {
            const query = messageText.value.slice(1).trim();
            filterDevices(query);
            showDeviceList.value = true;
        }
    };

    const sendMessage = async () => {
        if (!messageText.value.trim() || !selectedDeviceMac.value) {
            showGlobalNotification('消息发送失败：请先选择设备并输入消息内容', 'error');
            return;
        }

        sendingMessage.value = true;

        try {
            const targetAddr = selectedDeviceMac.value === 'broadcast' ? 'broadcast' : selectedDeviceMac.value;
            const messageContent = messageText.value.trim();
            
            // 确定target值
            let target = 'all'; // 默认target为all
            if (selectedTargetDevice.value) {
                // 如果有@提及的设备，使用该设备的原始标识作为target
                target = selectedTargetDevice.value.originalUser || selectedTargetDevice.value.mac || 'all';
            }

            let success;
            if (selectedDeviceMac.value === 'broadcast') {
                // 使用广播接口发送消息
                const response = await stpApi.broadcastMessage(messageContent, target);
                success = response.success;
            } else {
                // 使用普通发送接口
                success = await publishMessage(targetAddr, messageContent);
            }

            if (success) {
                // 创建发送的消息对象
                const sentMessage = {
                    msg: messageContent,
                    target: selectedDeviceMac.value === 'broadcast' ? target : 'p2p',
                    time: Math.floor(Date.now() / 1000),
                    user: "admin",
                    source_mac: ":::::",
                    receivedAt: Date.now()
                };

                // 确保目标设备的消息列表存在
                if (!messageDictionary.value[selectedDeviceMac.value]) {
                    messageDictionary.value[selectedDeviceMac.value] = [];
                }

                // 将消息添加到对应设备的消息列表中
                messageDictionary.value[selectedDeviceMac.value].unshift(sentMessage);

                // 将消息添加到历史消息列表中
                if (selectedDeviceMac.value) {
                    // 确保当前会话的历史消息列表存在
                    if (!messageHistory.value[selectedDeviceMac.value]) {
                        messageHistory.value[selectedDeviceMac.value] = [];
                    }
                    
                    const history = messageHistory.value[selectedDeviceMac.value];
                    // 检查当前消息是否与上一条消息相同，只有不同时才添加到历史记录
                    if (history.length === 0 || history[0] !== messageContent) {
                        // 将消息添加到历史列表开头
                        history.unshift(messageContent);
                        
                        // 确保历史列表长度不超过50条
                        if (history.length > 50) {
                            history.splice(50);
                        }
                    }
                }

                // 重置历史消息索引
                historyIndex.value = -1;
                tempMessage.value = '';

                // 重置exec命令状态，恢复输入框高度
                isExecCommand.value = false;

                // 清空输入框和目标设备
                messageText.value = '';
                selectedTargetDevice.value = null;
                showGlobalNotification('消息发送成功', 'success');
            } else {
                showGlobalNotification('消息发送失败', 'error');
            }
        } catch (error) {
            showGlobalNotification('发送消息时出错', 'error');
        } finally {
            sendingMessage.value = false;
        }
    };

