    const getAvatarColor = (deviceName) => {
        if (!deviceName) {
            deviceName = 'unknown';
        }

        const name = String(deviceName);
        let hash = 0;
        for (let i = 0; i < name.length; i++) {
            hash = name.charCodeAt(i) + ((hash << 5) - hash);
        }

        const h = Math.abs(hash % 360);
        const s = 70 + (hash % 20);
        const l = 50 + (hash % 10);

        return `linear-gradient(135deg, hsl(${h}, ${s}%, ${l}%), hsl(${h + 30}, ${s}%, ${l}%))`;
    };

    const getDeviceIconForMessage = (msg) => {
        const type = (msg.type || 'unknown').toLowerCase();
        const iconMap = {
            'cloud': 'fas fa-cloud',
            'monitor': 'fas fa-desktop',
            'all': 'fas fa-users',
            'admin': 'fas fa-user-cog',
            'unknown': 'fas fa-question-circle'
        };
        return iconMap[type] || iconMap.unknown;
    };

