    const getMessageSender = (msg) => {
        // 优先显示user
        if (msg.user) {
            return msg.user;
        }
        
        // 没有user，显示source_mac
        if (msg.source_mac) {
            // 检查source_mac是否为特殊值
            if (msg.source_mac === ':::::') {
                return 'admin';
            }
            if (msg.source_mac === 'localhost') {
                return 'localhost';
            }
            // 尝试获取昵称
            try {
                const nickname = getDeviceShowName(msg.source_mac);
                return nickname;
            } catch (error) {
                // 如果获取昵称失败，直接显示source_mac
                return msg.source_mac;
            }
        }
        
        // 什么都没有，显示unknown
        return 'unknown';
    };

    const formatRawMessage = (msg) => {
        if (typeof msg.msg === 'string') {
            return msg.msg;
        }
        return JSON.stringify(msg.msg, null, 2);
    };

    const getMessageClass = (msg) => {
        const message = typeof msg.msg === 'string' ? msg.msg.toLowerCase() : '';
        if (message.includes('on') || message === 'on') return 'on';
        if (message.includes('off') || message === 'off') return 'off';
        return '';
    };

