// src/utils/notificationHandler.js
import { ref } from 'vue';

// 全局通知管理器引用
const NotificationManagerRef = ref(null);

// 设置通知管理器的方法
export function setNotificationManager(manager) {
    NotificationManagerRef.value = manager;
}

// 显示全局通知的方法
export function showGlobalNotification(message, type='info') {
    if (NotificationManagerRef.value) {
        NotificationManagerRef.value.addMessage(message, type);
    } else {
        // 降级处理：使用控制台和原生 alert
        // 全局通知:
        alert(message);
    }
}

// 处理未捕获的 Promise 异常
export function setupGlobalNotificationHandling() {
    window.addEventListener('unhandledrejection', event => {
        const message = `未处理错误: ${event.reason?.message || event.reason || '未知错误'}`;
        showGlobalNotification(message, 'error');
    });

    window.addEventListener('error', event => {
        const message = `全局错误: ${event.message || '未知错误'}`;
        showGlobalNotification(message, 'error');
    });
}