// src/composables/useMonitor.js
import { ref } from 'vue';
import { deviceApi } from '@/services/stpApi';
import { showGlobalNotification } from '@/utils/notificationHandler.js';

export function useMonitor() {
    // 摄像头列表
    const cameras = ref([]);

    // 添加摄像头
    const addCamera = (cameraData) => {
        cameras.value.push({
            id: cameraData.id || Date.now().toString(),
            name: cameraData.name,
            ip: cameraData.ip,
            port: cameraData.port,
            streaming: cameraData.streaming || false
        });
    };

    // 删除摄像头
    const removeCamera = (cameraId) => {
        const index = cameras.value.findIndex(camera => camera.id === cameraId);
        if (index !== -1) {
            // 先停止流
            if (cameras.value[index].streaming) {
                stopStream(cameraId);
            }
            cameras.value.splice(index, 1);
        }
    };

    // 开始摄像头流
    const startStream = async (cameraId) => {
        const camera = cameras.value.find(c => c.id === cameraId);
        if (camera) {
            try {
                // 使用STP消息启动流
                const targetAddr = `${camera.ip}:${camera.port}`;
                await deviceApi.startCameraStream(targetAddr);
                camera.streaming = true;
                showGlobalNotification(`摄像头 ${camera.name} 流已启动`, 'success');
            } catch (error) {
                showGlobalNotification(`启动摄像头 ${camera.name} 流失败`, 'error');
                camera.streaming = false;
            }
        }
    };

    // 停止摄像头流
    const stopStream = async (cameraId) => {
        const camera = cameras.value.find(c => c.id === cameraId);
        if (camera) {
            try {
                // 使用STP消息停止流
                const targetAddr = `${camera.ip}:${camera.port}`;
                await deviceApi.stopCameraStream(targetAddr);
                camera.streaming = false;
                showGlobalNotification(`摄像头 ${camera.name} 流已停止`, 'info');
            } catch (error) {
                showGlobalNotification(`停止摄像头 ${camera.name} 流失败`, 'error');
                camera.streaming = false;
            }
        }
    };

    // 获取摄像头
    const getCamera = (cameraId) => {
        return cameras.value.find(camera => camera.id === cameraId);
    };

    // 获取所有摄像头
    const getAllCameras = () => {
        return cameras.value;
    };

    // 清空所有摄像头
    const clearCameras = () => {
        // 先停止所有流
        cameras.value.forEach(camera => {
            if (camera.streaming) {
                stopStream(camera.id);
            }
        });
        cameras.value = [];
    };

    return {
        // 状态
        cameras,

        // 方法
        addCamera,
        removeCamera,
        startStream,
        stopStream,
        getCamera,
        getAllCameras,
        clearCameras
    };
}
